    companion object {
        private val byId: Array<Cs2Op> = entries.sortedBy { it.id }.toTypedArray()
        private val byTsName: Map<String, Cs2Op> = entries.associateBy { it.tsName }

        operator fun get(id: Int): Cs2Op = find(id) ?: error("Unknown CS2 opcode $id")

        fun find(id: Int): Cs2Op? = byId.getOrNull(id)

        fun byTsName(name: String): Cs2Op? = byTsName[name]
    }
